/* From Uiverse.io by faxriddin20  - Tags: purple, button, download, #button */
.__UIV_SCOPE__ .download-btn {
  border: 2px solid rgb(168, 38, 255);
  background-color: white;
  width: 50px;
  height: 50px;
  border-radius: 10px;
  position: relative;
  z-index: 1;
  transition: all 0.2s ease;
  cursor: pointer;
}
.__UIV_SCOPE__ .download-btn svg {
  width: 25px;
  height: 25px;
  transition: all 0.3s ease;
}
.__UIV_SCOPE__ .download-btn:hover svg {
  fill: white;
}
.__UIV_SCOPE__ .download-btn:hover {
  background-color: rgb(168, 38, 255);
}
